import json, math, collections, random
from pathlib import Path
fixture = json.loads(Path("testdata/aws/xray/histogram_edges.json").read_text())
def rounded(v):
    return math.floor(v*1000+0.5)/1000
def reduce_histogram(samples):
    histogram=collections.Counter(rounded(v) for v in samples)
    values=sorted(histogram)
    if not values: return []
    total=len(samples); before=0; count=0; weighted_sum=0.0; result=[]
    def limit(before):
        angle=math.asin(2*before/total-1)+2*math.pi/100
        return total*(math.sin(min(math.pi/2,angle))+1)/2
    end=limit(before)
    def emit(count,weighted_sum):
        value=rounded(weighted_sum/count)
        if result and result[-1]["Value"]==value:
            result[-1]["Count"]+=count
        else:
            result.append({"Value":value,"Count":count})
    for value in values:
        weight=histogram[value]
        if count and before+count+weight>end:
            emit(count,weighted_sum); before+=count; count=0; weighted_sum=0; end=limit(before)
        count+=weight; weighted_sum+=value*weight
    emit(count,weighted_sum)
    return result
cases={name:[] for name in fixture["cases"]}
for observation in fixture["observations"]:
    if observation["path"]=="TraceSegments":
        for document in observation["input"]["TraceSegmentDocuments"]:
            doc=json.loads(document)
            cases[doc["annotations"]["kind"]].append(doc["end_time"]-doc["start_time"])
results={}
for name,samples in cases.items():
    reduced=reduce_histogram(samples)
    assert sum(b["Count"] for b in reduced)==len(samples)
    assert all(a["Value"]<b["Value"] for a,b in zip(reduced,reduced[1:]))
    assert len(reduced)<=100
    total_rounded=sum(rounded(v) for v in samples)
    error=abs(sum(b["Count"]*b["Value"] for b in reduced)-total_rounded)
    assert error<=0.0005*len(samples)+1e-8
    assert reduced==reduce_histogram(list(reversed(samples)))
    native=[]
    for o in fixture["observations"]:
        if o["path"]!="ServiceGraph": continue
        for s in o["output"].get("Services",[]):
            if s["Name"]!=fixture["prefix"]+"-"+name or (s.get("SummaryStatistics")or{}).get("TotalCount")!=len(samples): continue
            h=s["ResponseTimeHistogram"]
            assert sum(b["Count"] for b in h)==len(samples)
            assert s["SummaryStatistics"]["TotalResponseTime"]==rounded(sum(samples))
            native.append({"observation":o["label"],"bins":len(h),"max_weight":max(b["Count"] for b in h),"weighted_sum":sum(b["Count"]*b["Value"] for b in h)})
    assert native
    results[name]={"samples":len(samples),"rounded_unique":len(set(rounded(v) for v in samples)),"local_bins":len(reduced),"local_weighted_sum_error":error,"local_histogram":reduced,"native_readbacks":native}
rng=random.Random(314159)
for count in [1,2,80,256,1024,10000,100000]:
    samples=[rng.randrange(0,count+1)/1000 for _ in range(count)]
    out=reduce_histogram(samples)
    assert len(out)<=100
    assert sum(b["Count"] for b in out)==count
    assert abs(sum(b["Count"]*b["Value"] for b in out)-sum(rounded(v) for v in samples))<=0.0005*count+1e-6
analysis={"cases":results,"stress_sizes":[1,2,80,256,1024,10000,100000],"verification":"Python replay of the production reduction; no Go build/tests executed."}
